def kth_smallest_pair_distance(nums, k):
    n = len(nums)
    total_pairs = n * (n - 1) // 2
    if k < 1 or k > total_pairs:
        return -1
    a = sorted(nums)

    def pairs_leq(d):
        count = 0
        left = 0
        for right in range(n):
            while a[right] - a[left] > d:
                left += 1
            count += right - left
        return count

    lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if pairs_leq(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
